#!/usr/bin/env node
/**
 * Writes the live handoff for the deep-research review: one stable path that always describes
 * current repository state, so a reviewer working over days does not need a frozen tag and does
 * not need to ask anyone what has moved.
 *
 * Regenerated by `npm run validate`, so it cannot drift from the corpus it describes.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { collectUnits } from './review-units.mjs';

const OUT = 'docs/full-corpus/review/RESEARCH_HANDOFF.md';
const STATE = 'docs/full-corpus/review/research-state.json';

const git = (...args) => {
  try { return execFileSync('git', args, { encoding: 'utf8' }).trim(); }
  catch { return null; }
};

const families = collectUnits();
// Deliberately carries neither the head SHA nor the branch name. Either would make this file
// change on commits that touch nothing a reviewer cares about, or differ between two branches
// holding identical records — and a handoff that churns is one people stop reading. What a
// reviewer needs is stable: the unit fingerprints below, which move only when the candidate they
// cover moves. Whoever opened this file already knows which branch they are on.

let totalUnits = 0;
const byTask = { A: 0, B: 0, C: 0 };
const state = { families: {} };
for (const [family, { meta, units }] of families) {
  totalUnits += units.length;
  for (const u of units) byTask[u.task] += 1;
  state.families[family] = {
    record_id: meta.record_id,
    content_hash: meta.content_hash,
    units: units.map((u) => ({ id: u.id, task: u.task, fingerprint: u.fingerprint })),
  };
}
writeFileSync(STATE, `${JSON.stringify(state, null, 2)}\n`);

const L = [];
L.push('# Live handoff — deep-research review of the Full Corpus');
L.push('');
L.push('**Generated by `scripts/research-handoff.mjs` on every `npm run validate`. Do not edit.**');
L.push('');
L.push('This file is the answer to "what is current?" — check it rather than asking. It is rewritten');
L.push('from committed state on every validate run, so if it says something, that is what the corpus');
L.push('says right now.');
L.push('');
L.push('It carries no commit SHA and no branch name on purpose. Either would make this file change');
L.push('on commits that touch nothing you care about, and neither is what you need — the unit');
L.push('fingerprints are, and those move only when the candidate they cover moves.');
L.push('');
L.push('| | |');
L.push('|---|---|');
L.push(`| Executable set | ${families.size} families |`);
L.push(`| Review units | ${totalUnits} — ${byTask.A} × A (source descriptions), ${byTask.B} × B (whole-document), ${byTask.C} × C (re-source) |`);
L.push('');
L.push('Machine-readable equivalent: [`research-state.json`](research-state.json).');
L.push('');
L.push('## Read these first');
L.push('');
L.push('1. [`DEEP_RESEARCH_BRIEF.md`](DEEP_RESEARCH_BRIEF.md) — what six completed passes already');
L.push('   settled, so you do not re-ask those questions, and what the three remaining ones look for.');
L.push('2. [`research-tasks/README.md`](research-tasks/README.md) — the task index. One file per');
L.push('   family; work order C → B → A.');
L.push('3. [`README.md`](README.md) — the review index, if you want the whole history.');
L.push('');
L.push('## Your verdict does not go stale just because the corpus moved');
L.push('');
L.push('Every reviewable unit carries a **fingerprint** over the only material a verdict is about:');
L.push('the candidate\'s text, its basis, and its provenance. Put that fingerprint in your verdict.');
L.push('');
L.push('The record\'s own content hash covers the whole record, so repairing a citation in `pub1`');
L.push('moves it — and would invalidate a finding about `exp2` for no reason. The gate therefore');
L.push('checks **your unit**, not the record. A verdict is refused only when the thing you actually');
L.push('read has changed, and the refusal names it.');
L.push('');
L.push('So: work at your own pace, return verdicts as you finish them, and re-run the gate whenever');
L.push('you like. If something you reviewed has been repaired since, it will tell you which unit and');
L.push('you re-read that one. Nothing else you have returned is affected.');
L.push('');
L.push('```');
L.push('node scripts/ingest-research-verdicts.mjs');
L.push('```');
L.push('');
L.push('## Current fingerprints');
L.push('');
L.push('Fingerprints change only when that unit\'s own candidate changes. Compare against your');
L.push('verdicts to see what, if anything, needs re-reading.');
L.push('');
L.push('| Family | Unit | Task | Fingerprint |');
L.push('|---|---|---|---|');
for (const [family, { units }] of families) {
  for (const u of units) {
    L.push(`| [${family}](research-tasks/${family}.md) | \`${u.id}\` | ${u.task} | \`${u.fingerprint}\` |`);
  }
}
L.push('');
L.push('## What this review is and is not');
L.push('');
L.push('It is not the release gate and it sets nothing on any record. The corpus stays a');
L.push('release-candidate with `reviewed_by_human` false on all records until a human decides');
L.push('otherwise. What this makes possible is assessing that decision from repository state rather');
L.push('than from someone\'s memory of who looked at what.');
L.push('');
writeFileSync(OUT, `${L.join('\n')}\n`);
console.log(`✓ research handoff: ${families.size} families, ${totalUnits} units → ${OUT}`);
